-- Correction 03. Versioned only: do not apply without the reviewed remote preconditions.
-- It changes presentation, never the technical modality identity.
begin;
set local lock_timeout = '10s';
set local statement_timeout = '60s';

lock table public.units, public.modalities, public.student_modality_units,
  public.attendance, public.evaluations, public.trainings,
  public.training_exercises, public.evaluation_results in share row exclusive mode;

create temp table modality_security_snapshot on commit drop as
select c.relrowsecurity, c.relforcerowsecurity, c.relacl::text as relacl,
  coalesce((select jsonb_agg(to_jsonb(p) order by p.policyname) from pg_policies p
    where p.schemaname = 'public' and p.tablename = 'modalities'), '[]'::jsonb) as policies
from pg_class c where c.oid = 'public.modalities'::regclass;

do $preconditions$
declare audited public.modalities%rowtype;
begin
  if to_regprocedure('private.clean_modality_name_v1(text)') is null
    or to_regprocedure('private.modality_name_key_v1(text)') is null
    or to_regprocedure('private.set_modality_name_v1()') is null then
    raise exception 'Correction 03 aborted: Correction 02 normalization infrastructure is missing.';
  end if;

  if not exists (
    select 1 from pg_attribute where attrelid = 'public.modalities'::regclass
      and attname = 'name_key' and attnotnull and not attisdropped
  ) or not exists (
    select 1 from pg_constraint where conrelid = 'public.modalities'::regclass
      and conname = 'modalities_unit_name_key_key' and contype = 'u'
  ) or not exists (
    select 1 from pg_constraint where conrelid = 'public.modalities'::regclass
      and conname = 'modalities_name_key_nonempty' and contype = 'c'
  ) or not exists (
    select 1 from pg_trigger where tgrelid = 'public.modalities'::regclass
      and tgname = 'modalities_set_name_v1' and not tgisinternal and tgenabled <> 'D'
  ) then
    raise exception 'Correction 03 aborted: expected name_key constraints or trigger are missing.';
  end if;

  select * into audited from public.modalities where id = 13;
  if not found
    or audited.unit_id <> 13
    or audited.name <> 'futebol'
    or audited.name_key <> 'futebol'
    or audited.status <> 'active'
    or not exists (select 1 from public.units where id = 13 and organization_id = 15)
  then
    raise exception 'Correction 03 aborted: audited modality 13 no longer matches the approved state.';
  end if;

  select * into audited from public.modalities where id = 12;
  if not found or audited.name <> 'Natação' or audited.name_key <> 'natacao' then
    raise exception 'Correction 03 aborted: canonical modality 12 no longer matches the approved state.';
  end if;

  if exists (select 1 from public.student_modality_units where modality_id = 13)
    or exists (select 1 from public.attendance where modality_id = 13)
    or exists (select 1 from public.evaluations where modality_id = 13)
    or exists (select 1 from public.trainings t join public.student_modality_units s on s.id = t.student_modality_unit_id where s.modality_id = 13)
    or exists (select 1 from public.training_exercises x join public.trainings t on t.id = x.training_id join public.student_modality_units s on s.id = t.student_modality_unit_id where s.modality_id = 13)
    or exists (select 1 from public.evaluation_results r join public.evaluations e on e.id = r.evaluation_id where e.modality_id = 13)
  then
    raise exception 'Correction 03 aborted: audited modality 13 now has references.';
  end if;
end;
$preconditions$;

create or replace function private.modality_display_name_v2(value text)
returns text language plpgsql immutable strict security invoker
set search_path = ''
as $function$
declare
  cleaned text := private.clean_modality_name_v1(value);
  key text := private.modality_name_key_v1(value);
  lowered text;
  first_character text;
  capitalized_first text;
  candidate text;
begin
