revoke all on function private.modality_display_name_v2(text) from public, anon, authenticated, service_role;

create temp table modality_presentation_v2 on commit drop as
select id, unit_id, name as old_name, name_key as old_key,
  private.modality_display_name_v2(name) as proposed_name,
  private.modality_name_key_v1(private.modality_display_name_v2(name)) as proposed_key
from public.modalities;

do $presentation_checks$
begin
  if exists (select 1 from pg_temp.modality_presentation_v2 where old_key <> proposed_key) then
    raise exception 'Correction 03 aborted: proposed presentation changes a modality name_key.';
  end if;
  if exists (select 1 from pg_temp.modality_presentation_v2 group by unit_id, proposed_key having count(*) > 1) then
    raise exception 'Correction 03 aborted: proposed presentation conflicts with UNIQUE (unit_id, name_key).';
  end if;
end;
$presentation_checks$;

create or replace function private.set_modality_name_v1()
returns trigger language plpgsql security definer
set search_path = ''
as $function$
begin
  -- Restricted to transforming NEW through qualified pure helpers: no table
  -- access or dynamic SQL. Caller DML remains subject to the existing RLS.
  new.name := private.modality_display_name_v2(new.name);
  new.name_key := private.modality_name_key_v1(new.name);
  return new;
end;
$function$;
revoke all on function private.set_modality_name_v1() from public, anon, authenticated, service_role;

update public.modalities m
set name = proposed.proposed_name
from pg_temp.modality_presentation_v2 proposed
where proposed.id = m.id and m.name is distinct from proposed.proposed_name;

do $postconditions$
begin
  if not exists (select 1 from public.modalities where id = 13 and unit_id = 13 and name = 'Futebol' and name_key = 'futebol' and status = 'active') then
    raise exception 'Correction 03 aborted: audited modality 13 was not safely canonicalized.';
  end if;
  if not exists (select 1 from public.modalities where id = 12 and name = 'Natação' and name_key = 'natacao') then
    raise exception 'Correction 03 aborted: canonical modality 12 changed unexpectedly.';
  end if;
  if exists (select 1 from public.modalities where name_key = '' or private.modality_name_key_v1(name) <> name_key) then
    raise exception 'Correction 03 aborted: stored modality keys are inconsistent.';
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'public.modalities'::regclass and conname = 'modalities_unit_name_key_key' and contype = 'u')
    or not exists (select 1 from pg_constraint where conrelid = 'public.modalities'::regclass and conname = 'modalities_name_key_nonempty' and contype = 'c') then
    raise exception 'Correction 03 aborted: name_key constraints changed unexpectedly.';
  end if;
  if exists (
    select 1 from pg_temp.modality_security_snapshot s
    cross join lateral (select c.relrowsecurity, c.relforcerowsecurity, c.relacl::text as relacl from pg_class c where c.oid = 'public.modalities'::regclass) current
    where (s.relrowsecurity, s.relforcerowsecurity, s.relacl) is distinct from (current.relrowsecurity, current.relforcerowsecurity, current.relacl)
      or s.policies is distinct from coalesce((select jsonb_agg(to_jsonb(p) order by p.policyname) from pg_policies p where p.schemaname = 'public' and p.tablename = 'modalities'), '[]'::jsonb)
  ) then
    raise exception 'Correction 03 aborted: modalities RLS, policies or grants changed unexpectedly.';
  end if;
end;
$postconditions$;

commit;
